package com.ruoyi.ai.agent;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import static com.ruoyi.ai.agent.AgentJson.*;
public class B9OrdinaryResultMysqlTest extends TestCase {
    private A1TestFixture f;private AgentStore store;private ControlledWriteService writes;private ObjectNode source,snapshot,request;private long book;
    protected void setUp() throws Exception {
        f=new A1TestFixture();store=new AgentStore(f.db);String sql=new String(Files.readAllBytes(Paths.get(System.getProperty("a1.module"),"sql/ai_agent_controlled_write_v2.sql")),StandardCharsets.UTF_8);f.db.execute(sql.replaceAll("(?m)^--[^\\r\\n]*","").trim());writes=new ControlledWriteService(store,f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());for(String field:new String[]{"enabled","b8EffectEnabled","b9ResultEnabled"})A1TestFixture.inject(writes,field,true);
        snapshot=(ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\",\"out\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Source\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"Name\"},\"1\":{\"v\":\"Amount\"}},\"1\":{\"0\":{\"v\":\"A\"},\"1\":{\"v\":7}},\"2\":{\"0\":{\"v\":\"B\"},\"1\":{\"v\":9}}}},\"out\":{\"id\":\"out\",\"name\":\"Result\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{}}}}");book=f.seed(snapshot.toString());ObjectNode ws=f.runs.workspace(book,1);
        source=obj().put("runId",UUID.randomUUID().toString()).put("userId",1L).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("revision",hash(snapshot)).put("status","COMPLETED").put("goal","只读数据集").put("version",0).put("eventSeq",0);source.set("plan",obj().set("steps",arr().add(obj().put("tool","build_dataset").put("status","SUCCEEDED"))));
        f.db.update("insert into ai_agent_run(run_id,user_id,workbook_id,branch_id,request_id,request_hash,status,state_json,row_version,updated_at,created_at) values(?,?,?,?,?,?,'COMPLETED',?,0,now(3),now(3))",text(source,"runId"),1,book,source.path("branchId").asLong(),UUID.randomUUID().toString(),hash(source),source.toString());
        ObjectNode read=obj().put("sheetId","s").put("range","A1:B3").put("headerRow",true).put("includeHidden",true).put("includeFiltered",true).put("formulaPolicy","reject");new AgentTools(store).execute(source,"build_dataset",read,snapshot);
        ArrayNode list=writes.resultArtifacts(book,1);assertEquals(1,list.size());request=obj().put("entryPoint","ordinary-ai").put("requestId",UUID.randomUUID().toString()).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("activeSheetId","out").put("overwrite","empty-only");for(String key:new String[]{"loadedRevision","expectedDraftVersion","expectedBranchVersion"})request.set(key,ws.path(key.equals("expectedDraftVersion")?"draftVersion":key.equals("expectedBranchVersion")?"branchVersion":key));request.set("writeScopes",arr().add(obj().put("sheetId","out").put("range","A1:B3")));request.set("resultArtifact",list.get(0).path("selection"));request.set("resultTarget",obj().put("sheetId","out").put("range","A1:B3"));
    }
    private ObjectNode create(){return writes.create(request,1);}
    private ObjectNode claim(ObjectNode r){return writes.claim(text(r,"runId"),1,obj().put("transportVersion",2).put("clientId","ordinary-b9").set("fencingToken",r.path("fencingToken")));}
    private ObjectNode receipt(JsonNode m){ObjectNode r=obj().put("transportVersion",2).put("ok",true);for(String key:new String[]{"callId","effectId","claimToken","argsHash","fencingToken"})r.set(key,m.path(key));ArrayNode cells=arr();for(JsonNode c:m.path("cells")){ObjectNode cell=obj().put("sheetId",text(c,"sheetId")).put("row",c.path("row").asInt()).put("column",c.path("column").asInt()).put("formula","");cell.set("value",c.path("value"));cells.add(cell);}r.set("cells",cells);return r;}
    private void reject(Runnable fn){try{fn.run();fail("untrusted ordinary result accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    private void mutateSource(){f.db.update("update ai_agent_run set state_json=? where run_id=?",source.toString(),text(source,"runId"));}
    private void corrupt(){f.db.update("update ai_analysis_artifact set content_json=json_set(content_json,'$.data.rows[0].Amount',999) where artifact_id=?",request.path("resultArtifact").path("resultRef").asText());}
    private void noCall(){assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_tool_call c join ai_agent_run r on r.run_id=c.run_id where r.workbook_id=? and r.run_id<>?",Integer.class,book,text(source,"runId")).intValue());assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_lease where workbook_id=? and run_id is not null",Integer.class,book).intValue());}
    public void testSelectionCreationSaveAndDuplicateIdentity(){ObjectNode r=create();assertFalse(text(r,"runId").equals(text(source,"runId")));assertEquals(text(r,"runId"),text(create(),"runId"));ObjectNode m=claim(r);assertEquals(text(source,"runId"),m.path("resultSource").path("runId").asText());ObjectNode receipt=receipt(m),saved=writes.receipt(text(r,"runId"),1,receipt);assertEquals("COMPLETED",saved.path("status").asText());assertEquals(m.path("resultSource"),saved.path("lastControlledResult").path("executedChange").path("resultSource"));corrupt();writes.receipt(text(r,"runId"),1,receipt);JsonNode actual=parse(String.valueOf(f.status(book).get("content")));assertEquals(snapshot.path("sheets").path("s"),actual.path("sheets").path("s"));assertEquals(9,actual.path("sheets").path("out").path("cellData").path("2").path("1").path("v").asInt());}
    public void testForeignUserAndWorkbookDenied(){reject(()->writes.resultArtifacts(book,2));reject(()->writes.create(request,2));source.put("workbookId",book+1);mutateSource();reject(()->create());noCall();}
    public void testDifferentBranchAndUnknownArtifactDenied(){source.put("branchId",source.path("branchId").asLong()+1);mutateSource();reject(()->create());source.put("branchId",request.path("branchId").asLong());mutateSource();((ObjectNode)request.path("resultArtifact")).put("resultRef",UUID.randomUUID().toString());reject(()->create());noCall();}
    public void testSelectionFrozenDigestAndUnexpectedFieldsDenied(){ObjectNode selected=(ObjectNode)request.path("resultArtifact"),original=selected.deepCopy();selected.put("dataDigest","model-forged");reject(()->create());request.set("resultArtifact",original.deepCopy().put("values","forged"));reject(()->create());request.set("resultArtifact",original);request.set("actions",arr());reject(()->create());noCall();}
    public void testStaleOrWritingSourceDenied(){source.put("revision","old");mutateSource();reject(()->create());source.put("revision",hash(snapshot));((ObjectNode)source.path("plan").path("steps").get(0)).put("tool","write_result");mutateSource();reject(()->create());assertEquals(0,writes.resultArtifacts(book,1).size());noCall();}
    public void testLegacyArtifactNotSelectable(){String id=store.artifact(source,obj().set("columns",arr().add("x")));assertEquals(1,writes.resultArtifacts(book,1).size());((ObjectNode)request.path("resultArtifact")).put("resultRef",id);reject(()->create());noCall();}
    public void testSourceSheetShapeAndScopeDenied(){ObjectNode original=request.deepCopy();request.set("resultTarget",obj().put("sheetId","s").put("range","A1:B3"));reject(()->create());request=original.deepCopy();((ObjectNode)request.path("resultTarget")).put("range","A1:B2");reject(()->create());request=original.deepCopy();request.set("writeScopes",arr().add(obj().put("sheetId","out").put("range","A1")));reject(()->create());noCall();}
    public void testSourceChangedBeforeClaimAndAfterClaimDenied(){ObjectNode r=create();corrupt();reject(()->claim(r));assertNull(f.status(book).get("workingState"));}
    public void testSourceRevokedAfterClaimDenied(){ObjectNode r=create(),m=claim(r);source.put("status","CANCELLED");mutateSource();reject(()->writes.receipt(text(r,"runId"),1,receipt(m)));assertNull(f.status(book).get("workingState"));}
    public void testContentChangedAfterClaimDenied(){ObjectNode r=create(),m=claim(r);corrupt();reject(()->writes.receipt(text(r,"runId"),1,receipt(m)));assertNull(f.status(book).get("workingState"));}
    public void testGateOffFailsClosed() throws Exception {A1TestFixture.inject(writes,"b9ResultEnabled",false);reject(()->writes.resultArtifacts(book,1));reject(()->create());noCall();}
    public void testSourceWriteHistoryIsNotLaundered(){source.set("completedSteps",arr().add(obj().put("tool","apply_actions")));mutateSource();reject(()->create());noCall();}
}
